(async () => {
  const { env } = process;
  if (!env.TEXT) throw new Error('Missing TEXT env var');
  if (!env.OUTPUT_PATH) throw new Error('Missing OUTPUT_PATH env var');
  globalThis.text = env.TEXT;
  globalThis.outputPath = env.OUTPUT_PATH;
  const mod = await import('qr-image');
  const pkg = mod.default || mod;
  if (typeof pkg.image !== 'function') throw new Error('qr-image: required method image not in exports');
  globalThis.qr = pkg;
})();

(async () => {
  const { createWriteStream } = await import('node:fs');
  const { pipeline } = await import('node:stream');
  const { promisify } = await import('node:util');
  const streamPipeline = promisify(pipeline);
  const qr = globalThis.qr;
  const text = globalThis.text;
  const outPath = globalThis.outputPath;
  const pngStream = qr.image(text, { type: 'png' });
  const outStream = createWriteStream(outPath);
  await streamPipeline(pngStream, outStream);
})();

